 source='<template><style>'+css+'</style>'+f'<div id="root" data-composition-id="{name}" data-width="1920" data-height="1080">'+''.join(text)+f'</div><script>const tl=gsap.timeline({{paused:true}});'+''.join(tweens)+f'window.__timelines["{name}"]=tl;</script></template>'
